# pak展開 (GARbro非対応の独自形式)
# 構造: 64バイト単位のテーブル → 各ファイル本体を連続で格納
#   先頭エントリ: 'DATA$TOP' + 64bit(エントリ数, 先頭自身を含む)
#   以降のエントリ: ファイル名(cp932, NUL終端, 以降は不定値) 56バイト + 32bit(サイズ) + 4バイト(0)
# 同名ファイルは後に展開したもので上書き
def extract_pak(pak: Path, out_dir: Path):
	pak = Path(pak)
	out_dir = Path(out_dir)

	with pak.open('rb') as f:
		head = f.read(64)
		if head[:8] != b'DATA$TOP': raise RuntimeError(f'{pak.name}: 未対応のpak形式')
		count = int.from_bytes(head[56:64], 'little')

		entries = []
		offset = count * 64
		for _ in range(count - 1):
			e = f.read(64)
			name = e[:56].split(b'\0')[0].decode('cp932').replace('\\', '/')
			size = int.from_bytes(e[56:60], 'little')
			parts = [p for p in name.split('/') if p]
			if not parts or '..' in parts or ':' in parts[0]: raise RuntimeError(f'{pak.name}: 不正なファイル名 {name}')
			entries.append(('/'.join(parts), size, offset))
			offset += size
		if offset != pak.stat().st_size: raise RuntimeError(f'{pak.name}: テーブルとファイルサイズが一致しません')

	# 同名パス(同一pak内の重複)は上書き順を保つため宛先ごとにまとめ、グループ単位で直列展開する
	# (グループ間はI/O待ちが大半のためスレッドプールで並列化し、voice.pak等の大量ファイルを高速化)
	groups = {}
	for name, size, offset in entries:
		groups.setdefault(name, []).append((size, offset))
	for name in groups:
		(out_dir / name).parent.mkdir(parents=True, exist_ok=True)

	def extract_group(name, items):
		dst = out_dir / name
		conflicts = []
		exists = dst.exists()
		with pak.open('rb') as f:
			for i, (size, offset) in enumerate(items):
				if exists or i > 0: conflicts.append(name)
				f.seek(offset)
				with dst.open('wb') as w:
					left = size
					while left > 0:
						buf = f.read(min(left, 1 << 20))
						if not buf: raise RuntimeError(f'{pak.name}: {name} が途中で終了しています')
						w.write(buf)
						left -= len(buf)
		return conflicts

	with concurrent.futures.ThreadPoolExecutor() as ex:
		overwritten = [n for r in ex.map(lambda kv: extract_group(*kv), groups.items()) for n in r]

	return overwritten


# リソース展開 (data → updata → bgm → voice の順に上書き展開し、競合したファイル名のリストを返す)
def extract_resource(values: dict, values_ex: dict, pre_converted_dir: Path):
	input_dir = Path(values['input_dir'])
	pre_converted_dir = Path(pre_converted_dir)
	pre_converted_dir.mkdir(parents=True, exist_ok=True)

	conflicts = []
	for arc_name in ['data', 'updata', 'bgm', 'voice']:
		conflicts += [f'{arc_name}.pak: {n}' for n in extract_pak(Path(input_dir / f'{arc_name}.pak'), pre_converted_dir)]

	# オープニング動画コピー
	shutil.copy(Path(input_dir / 'doko_op.mpg'), pre_converted_dir)

	return conflicts


